class Solution {
public:
    unordered_set<TreeNode*> target;
    TreeNode* dfs(TreeNode* node) {
        if (!node || target.count(node)) return node;
        TreeNode* left = dfs(node->left);
        TreeNode* right = dfs(node->right);
        if (left && right) return node;
        return left ? left : right;
    }
    TreeNode* lowestCommonAncestor(TreeNode* root, vector<TreeNode*>& nodes) {
        target = unordered_set<TreeNode*>(nodes.begin(), nodes.end());
        return dfs(root);
    }
};

class Solution {
    private Set<TreeNode> target;
    private TreeNode dfs(TreeNode node) {
        if (node == null || target.contains(node)) return node;
        TreeNode left = dfs(node.left);
        TreeNode right = dfs(node.right);
        if (left != null && right != null) return node;
        return left != null ? left : right;
    }
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode[] nodes) {
        target = new HashSet<>();
        for (TreeNode n : nodes) target.add(n);
        return dfs(root);
    }
}

var lowestCommonAncestor = function(root, nodes) {
    const target = new Set(nodes);
    function dfs(node) {
        if (!node || target.has(node)) return node;
        const left = dfs(node.left);
        const right = dfs(node.right);
        if (left && right) return node;
        return left || right;
    }
    return dfs(root);
};
